//! `ork init` and `ork scan`.

use std::collections::BTreeSet;
use std::path::Path;

use orkstage_scan::{DetectedResource, ScanReport};
use serde_json::Value;

use super::template::{metadata, set_metadata};
use super::{client, default_name, resolve_path, scan_project};
use crate::cli::{InitArgs, OutputFormat, ScanArgs};
use crate::config::{Binding, Ctx, ORK_DIR, ProjectConfig, render_project_config};
use crate::error::{CliError, Result};
use crate::output::{self, dim, heading};
use crate::walk::Walked;

const GITIGNORE: &str =
    "# Local-only files written by `ork` (regenerated by `ork scan --write`).\ninventory.json\n*.local.toml\ncache/\n";

pub fn write_outputs(ork_dir: &Path, report: &ScanReport) -> Result<()> {
    std::fs::create_dir_all(ork_dir).map_err(|e| CliError::io(format!("creating {}", ork_dir.display()), e))?;
    let inv = serde_json::to_string_pretty(report).map_err(|e| CliError::failed(e.to_string(), None))? + "\n";
    let write = |name: &str, content: &str| {
        let p = ork_dir.join(name);
        std::fs::write(&p, content).map_err(|e| CliError::io(format!("writing {}", p.display()), e))
    };
    write("inventory.json", &inv)?;
    write("template.yaml", &report.template)?;
    if !ork_dir.join(".gitignore").exists() {
        write(".gitignore", GITIGNORE)?;
    }
    Ok(())
}

/// Written when the scan finds nothing deployable, so the first template still validates.
pub fn starter_template(name: &str) -> String {
    let display: String = name
        .split('-')
        .filter(|w| !w.is_empty())
        .map(|w| {
            let mut c = w.chars();
            c.next().map(|f| f.to_ascii_uppercase().to_string() + c.as_str()).unwrap_or_default()
        })
        .collect::<Vec<_>>()
        .join(" ");
    format!(
        "# Starter written by `ork init`: nothing deployable was detected in this directory.\n\
         # Replace the image with yours (a digest or a catalog reference) and add what the app needs.\n\
         apiVersion: platform/v1\n\
         kind: EnvironmentTemplate\n\
         metadata:\n  name: {name}\n  version: 0.1.0\n  displayName: {display}\n  \
         description: \"Starter: one network and one web service.\"\n  profile: starter\n\
         spec:\n  plans: [STARTER, GROWTH]\n  placements:\n    - name: primary\n      \
         description: \"Bind any cloud target.\"\n  resources:\n    - id: network\n      type: network\n    \
         - id: web\n      type: compute.container-service\n      image: catalog://sample-api\n      port: 8080\n"
    )
}

/// Template and slot names of a marketplace listing, renamed to this project (version 0.1.0).
async fn from_marketplace(ctx: &Ctx, slug: &str, name: &str) -> Result<(String, Vec<String>)> {
    let api = client(ctx)?;
    let listing: Value = api.get(&format!("/marketplace/listings/{slug}"), &[]).await?;
    let source = listing.pointer("/template/source").and_then(Value::as_str).ok_or_else(|| {
        CliError::not_found(format!("marketplace listing \"{slug}\" has no published template"), None)
    })?;
    let renamed = set_metadata(&set_metadata(source, "name", name), "version", "0.1.0");
    if metadata(&renamed).0.as_deref() != Some(name) {
        return Err(CliError::failed(format!("could not rename the template of \"{slug}\""), None));
    }
    let slots = listing
        .pointer("/template/placements")
        .and_then(Value::as_array)
        .map(|a| a.iter().filter_map(|p| p.get("name").and_then(Value::as_str).map(str::to_string)).collect())
        .unwrap_or_default();
    Ok((renamed, slots))
}

fn slots(report: &ScanReport) -> BTreeSet<String> {
    let mut s: BTreeSet<String> = report
        .resources
        .iter()
        .filter_map(|r| r.properties.get("placement").and_then(Value::as_str).map(str::to_string))
        .collect();
    s.insert("primary".into());
    s
}

pub async fn init(ctx: &Ctx, args: InitArgs) -> Result<()> {
    let root = resolve_path(ctx, args.path.as_deref());
    let ork_dir = root.join(ORK_DIR);
    if ork_dir.join("config.toml").exists() && !args.force {
        return Err(CliError::usage(
            format!("{} is already initialized", root.display()),
            Some("use `ork scan --write` to refresh the template, or `ork init --force` to start over".into()),
        ));
    }
    let interactive = ctx.interactive && !args.yes;
    let prompt_err = |e: dialoguer::Error| CliError::failed(e.to_string(), None);

    let default = args.name.clone().or_else(|| default_name(&root)).unwrap_or_else(|| "app".into());
    let name = if interactive && args.name.is_none() {
        dialoguer::Input::<String>::new()
            .with_prompt("Template name")
            .default(default)
            .validate_with(|s: &String| -> Result<(), String> {
                let ok = s.len() >= 2
                    && s.starts_with(|c: char| c.is_ascii_lowercase())
                    && s.chars().all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-');
                if ok { Ok(()) } else { Err("lowercase letters, digits and dashes; starts with a letter".into()) }
            })
            .interact_text()
            .map_err(prompt_err)?
    } else {
        default
    };
    if !(name.len() >= 2
        && name.starts_with(|c: char| c.is_ascii_lowercase())
        && name.chars().all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-'))
    {
        return Err(CliError::usage(
            format!("invalid template name {name:?}"),
            Some("use lowercase letters, digits and dashes, starting with a letter".into()),
        ));
    }

    let (mut report, walked) = scan_project(ctx, &root, None, Some(name.clone()))?;
    let mut slot_names = slots(&report);
    let origin = if let Some(slug) = &args.from {
        let (source, from_slots) = from_marketplace(ctx, slug, &name).await?;
        report.template = source;
        slot_names = from_slots.into_iter().collect();
        format!("Template: marketplace listing {slug}, renamed {name}.")
    } else if report.resources.is_empty() {
        report.template = starter_template(&name);
        "Template: nothing deployable was detected, so .ork/template.yaml is a starter (one web service).".into()
    } else {
        String::new()
    };

    let tenant = match args.tenant.clone().or_else(|| ctx.tenant()) {
        Some(t) => Some(t),
        None if interactive => {
            let t: String = dialoguer::Input::new()
                .with_prompt("Tenant slug (empty to set later)")
                .allow_empty(true)
                .interact_text()
                .map_err(prompt_err)?;
            (!t.trim().is_empty()).then(|| t.trim().to_string())
        }
        None => None,
    };
    let envs = ["staging", "production", "development", "sandbox"];
    let environment = match args.environment.clone() {
        Some(e) => e,
        None if interactive => {
            let i = dialoguer::Select::new()
                .with_prompt("Environment of this project's instance")
                .items(envs)
                .default(0)
                .interact()
                .map_err(prompt_err)?;
            envs[i].to_string()
        }
        None => "staging".into(),
    };
    let slug: String = format!("{name}-{environment}").chars().take(63).collect();

    let mut config = ProjectConfig { api_url: ctx.api_url.clone(), tenant, ..Default::default() };
    config.template.name = Some(name.clone());
    config.instance.slug = Some(slug.clone());
    config.instance.environment = Some(environment);
    for s in slot_names {
        // Left for the user: the cloud target and region of each slot.
        config.placements.insert(s, Binding::default());
    }
    let mut text = render_project_config(&config);
    // Unbound slots are written as commented examples.
    text = text
        .lines()
        .map(|l| {
            if l.ends_with("{ target = \"\", region = \"\" }") {
                let slot = l.split(' ').next().unwrap_or("primary");
                format!("# {slot} = {{ target = \"my-cloud-target\", region = \"us-east-1\" }}")
            } else {
                l.to_string()
            }
        })
        .collect::<Vec<_>>()
        .join("\n")
        + "\n";

    write_outputs(&ork_dir, &report)?;
    let cfg_path = ork_dir.join("config.toml");
    std::fs::write(&cfg_path, text).map_err(|e| CliError::io(format!("writing {}", cfg_path.display()), e))?;

    if ctx.json() {
        output::print_json(&serde_json::json!({
            "root": root.display().to_string(),
            "files": [".ork/config.toml", ".ork/template.yaml", ".ork/inventory.json", ".ork/.gitignore"],
            "template": name,
            "templateOrigin": if args.from.is_some() { "marketplace" } else if report.resources.is_empty() { "starter" } else { "scan" },
            "instance": slug,
            "resources": report.resources.len(),
            "unmapped": report.unmapped.len(),
            "warnings": report.warnings,
        }));
        return Ok(());
    }
    print_summary(ctx, &report, &walked);
    eprintln!();
    if !origin.is_empty() {
        eprintln!("{origin}");
    }
    eprintln!("Created {}/ with config.toml, template.yaml, inventory.json and .gitignore.", ork_dir.display());
    eprintln!("Next: review .ork/template.yaml, then `ork template validate` and `ork template push`.");
    Ok(())
}

pub fn scan(ctx: &Ctx, args: ScanArgs) -> Result<()> {
    let root = resolve_path(ctx, args.path.as_deref());
    let (report, walked) = scan_project(ctx, &root, args.max_file_bytes, None)?;
    if args.write {
        let project = ctx.require_project()?;
        write_outputs(&project.ork_dir(), &report)?;
        output::note(ctx, &format!("Updated {0}/inventory.json and {0}/template.yaml", project.ork_dir().display()));
    }
    let format = args.format.unwrap_or(ctx.output);
    if format == OutputFormat::Json {
        output::print_json(&report);
        return Ok(());
    }
    print_summary(ctx, &report, &walked);
    Ok(())
}

fn details(r: &DetectedResource) -> String {
    const KEYS: &[&str] = &[
        "replicas",
        "cpu",
        "memoryMiB",
        "port",
        "public",
        "size",
        "storageGiB",
        "highAvailability",
        "version",
        "fifo",
        "deadLetter",
        "versioning",
        "availabilityZones",
        "placement",
        "target",
        "inferred",
    ];
    let mut parts: Vec<String> = KEYS
        .iter()
        .filter_map(|k| r.properties.get(*k).map(|v| format!("{k}={}", v.to_string().trim_matches('"'))))
        .collect();
    if let Some(routes) = r.properties.get("routes").and_then(Value::as_array) {
        let s: Vec<String> =
            routes.iter().map(|x| x.get("service").and_then(Value::as_str).unwrap_or("?").to_string()).collect();
        parts.push(format!("routes={}", s.join("+")));
    }
    parts.join(" ")
}

fn evidence(r: &DetectedResource) -> String {
    let Some(first) = r.sources.first() else { return "inferred".into() };
    let loc = match first.line {
        Some(l) => format!("{}:{l}", first.file),
        None => first.file.clone(),
    };
    let mut kinds: Vec<&str> = r.sources.iter().map(|s| s.kind.as_str()).collect();
    kinds.dedup();
    let more = if r.sources.len() > 1 { format!(" +{}", r.sources.len() - 1) } else { String::new() };
    format!("{loc} ({}){more}", kinds.join(","))
}

pub fn print_summary(ctx: &Ctx, report: &ScanReport, walked: &Walked) {
    let kinds: Vec<String> = report.detectors.iter().map(|d| format!("{} {}", d.kind.as_str(), d.files)).collect();
    eprintln!(
        "{}",
        dim(
            ctx,
            &format!(
                "Scanned {} of {} files ({:.1} KiB): walk {} ms, scan {} ms{}{}",
                walked.files.len(),
                walked.visited,
                walked.bytes as f64 / 1024.0,
                walked.elapsed_ms,
                walked.scan_ms,
                if kinds.is_empty() { "" } else { " · " },
                kinds.join(" · ")
            )
        )
    );
    crate::outln!("{}", heading(ctx, &format!("Resources ({})", report.resources.len())));
    if report.resources.is_empty() {
        crate::outln!("  none detected");
    } else {
        let mut t =
            output::table(ctx, &["ID", "TYPE", "PROVIDER", "IMPLEMENTATION", "CONFIDENCE", "DETAILS", "EVIDENCE"]);
        for r in &report.resources {
            t.add_row(vec![
                comfy_table::Cell::new(&r.id),
                comfy_table::Cell::new(r.kind.as_str()),
                comfy_table::Cell::new(r.provider.map(|p| p.as_str()).unwrap_or("-")),
                comfy_table::Cell::new(r.implementation.as_deref().unwrap_or("-")),
                output::status_cell(ctx, &format!("{:?}", r.confidence).to_lowercase()),
                comfy_table::Cell::new(details(r)),
                comfy_table::Cell::new(evidence(r)),
            ]);
        }
        crate::outln!("{t}");
    }
    if !report.connections.is_empty() {
        crate::outln!("{}", heading(ctx, &format!("Connections ({})", report.connections.len())));
        let mut t = output::table(ctx, &["FROM", "TO", "PROTOCOL", "PORT", "EVIDENCE"]);
        for c in &report.connections {
            t.add_row(vec![
                c.from.clone(),
                c.to.clone(),
                c.protocol.clone(),
                c.port.map(|p| p.to_string()).unwrap_or_else(|| "-".into()),
                c.evidence.clone(),
            ]);
        }
        crate::outln!("{t}");
    }
    if !report.unmapped.is_empty() {
        crate::outln!("{}", heading(ctx, &format!("Unmapped ({})", report.unmapped.len())));
        let mut t = output::table(ctx, &["SOURCE", "TYPE", "REASON"]);
        for u in &report.unmapped {
            let loc = match u.source.line {
                Some(l) => format!("{}:{l} {}", u.source.file, u.source.address),
                None => format!("{} {}", u.source.file, u.source.address),
            };
            t.add_row(vec![loc, u.kind.clone(), u.reason.clone()]);
        }
        crate::outln!("{t}");
    }
    if !report.warnings.is_empty() {
        crate::outln!("{}", heading(ctx, &format!("Warnings ({})", report.warnings.len())));
        for w in &report.warnings {
            crate::outln!("  - {w}");
        }
    }
}
